// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, deleteLinks } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "name": "testbot idem A",
        "tags": [],
        "url": "https://testbot.example.com/archive-idem"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody, 200);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot idem A");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://testbot.example.com/archive-idem");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(linksPostResponse, "response.archiveStatus"), 'archiveStatus').toBe("pending");
    expect(getResponseValue(linksPostResponse, "response.archiveJobId"), 'archiveJobId').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

    // Request Body
    const linksPost1RequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "name": "testbot idem B",
        "tags": [],
        "url": "https://testbot.example.com/archive-idem"
    }`;

    const linksPost1Response = await createLink(client, headers, linksPost1RequestBody, 200);
    expect(linksPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPost1Response, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPost1Response, "response.name"), 'name').toBe("testbot idem B");
    expect(getResponseValue(linksPost1Response, "response.url"), 'url').toBe("https://testbot.example.com/archive-idem");
    expect(getResponseValue(linksPost1Response, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPost1Response, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(linksPost1Response, "response.archiveStatus"), 'archiveStatus').toBe("pending");

    const linkId = getResponseValue(linksPostResponse, "response.id");
    const linkId1 = getResponseValue(linksPost1Response, "response.id");
    expect(linkId1, 'the same url creates a second, distinct link').not.toBe(linkId);

    // Same URL -> one archive job: the second create reuses the first job's id.
    expect(getResponseValue(linksPost1Response, "response.archiveJobId"), 'archiveJobId').toBe(getResponseValue(linksPostResponse, "response.archiveJobId"));

    const linksDeleteResponse = await deleteLinks(client, headers, [linkId, linkId1], 200);
    expect(linksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksDeleteResponse, "response.count"), 'count').toBe(2);
});
